<?php
use Marketplace\Bus\Repository\IncidentRepository as Incidents;
$incidents ??= (new Incidents(db()))->listing($current, [], (int) $case['id']);
?>
<section class="panel detail-panel"><div class="section-heading"><div><h2>Incidentes relacionados</h2><p class="muted">Defectos del caso disponibles para tu cuenta.</p></div><a class="button-secondary" href="<?= e(url('/formularios/incidentes/nuevo?caso_id=' . $case['id'])) ?>">Registrar incidente desde este caso →</a></div>
